settings.custom_css:
.container {
  position: relative; /* Essencial para posicionar o elemento ::after */
  width: 800px;
  height: 400px;
  background-color: #1a1a1a;
  border: 1px solid #333; /* Borda da caixa principal */
  padding-bottom: 5px; /* Adiciona espaço para a linha inferior, se a linha for fina */
}

/* Cria a linha inferior com gradiente */
.container::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 5%; /* Começa um pouco para dentro */
  width: 90%; /* Termina um pouco para dentro (total: 5% + 90% + 5% = 100%) */
  height: 2px; /* Espessura da linha */

  /* O gradiente que vai sumindo nas pontas */
  background: linear-gradient(
    to right, 
    transparent 0%,      /* Totalmente transparente no início */
    #FF5733 20%,         /* Cor no corpo (20% do caminho) */
    #FF5733 80%,         /* Cor no corpo (até 80% do caminho) */
    transparent 100%     /* Totalmente transparente no final */
  );
}

.container {
  /* Propriedades básicas do seu container */
  width: 800px;
  height: 400px;
  background-color: #1a1a1a;
  border: 1px solid #333; /* Uma borda sutil em volta, se desejar */

  /* Gradiente na parte inferior usando box-shadow */
  /*
    Valores:
    - 0 5px (offset X e Y): Faz a sombra descer 5px (o que simula a linha)
    - 10px (blur): Suaviza o gradiente nas laterais
    - -5px (spread): Contrai a área da sombra para que ela não cubra a caixa
    - linear-gradient(...): O gradiente de cor da linha
  */
  box-shadow: 
    0 5px 10px -5px rgba(255, 87, 51, 0.7), /* Simula a linha central (opcional) */
    0 5px 15px -5px rgba(255, 87, 51, 0.5) inset; /* O gradiente na borda (opcional) */

  /* A solução mais direta e limpa para o gradiente na borda: */
  border-bottom: 2px solid transparent; /* Garante que a borda inferior está lá */
}

